// Reusable generation and check recipe for the weekly reference fixture.
// Default mode is check-only and needs no git object: it verifies the
// committed fixture, provenance, loader pins, and harness hash.
// When the pinned implementation object exists locally, it also regenerates
// via git archive and compares bytes to the committed fixture.
// Pass --write to recreate a missing fixture from git (fails unless the
// regenerated bytes match the recorded hashes).
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { gunzipSync } from 'node:zlib';
import { execFileSync } from 'node:child_process';
import {
  WEEKLY_IMPLEMENTATION_REVISION,
  WEEKLY_IMPLEMENTATION_TREE,
  REPLAY_HARNESS_SHA256,
  WEEKLY_ARCHIVE_B64_SHA256,
  WEEKLY_ARCHIVE_SHA256,
  WEEKLY_ARCHIVE_UNCOMPRESSED_SHA256,
} from './weekly-reference.mjs';

const fixtureUrl = new URL('./fixtures/weekly-77d8049-src-package.tar.gz.b64', import.meta.url);
const provenanceUrl = new URL('./fixtures/weekly-77d8049-src-package.provenance.json', import.meta.url);
const harnessUrl = new URL('./fixtures/weekly-77d8049-aa-replay.mjs', import.meta.url);
const root = fileURLToPath(new URL('..', import.meta.url));
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');

async function main() {
  const write = process.argv.includes('--write');
  const failures = [];
  const check = (name, actual, expected) => {
    const ok = actual === expected;
    console.log(`${ok ? 'ok' : 'FAIL'} ${name}: ${actual}`);
    if (!ok) failures.push(`${name}: expected ${expected}, got ${actual}`);
  };
  const provenance = JSON.parse(await readFile(provenanceUrl, 'utf8'));
  check('provenance implementation revision', provenance.implementation?.revision, WEEKLY_IMPLEMENTATION_REVISION);
  check('provenance implementation tree', provenance.implementation?.tree, WEEKLY_IMPLEMENTATION_TREE);
  check('provenance base64 hash', provenance.archive?.base64Sha256, WEEKLY_ARCHIVE_B64_SHA256);
  check('provenance compressed hash', provenance.archive?.compressedSha256, WEEKLY_ARCHIVE_SHA256);
  check('provenance uncompressed hash', provenance.archive?.uncompressedSha256, WEEKLY_ARCHIVE_UNCOMPRESSED_SHA256);
  check('provenance harness hash', provenance.harness?.sha256, REPLAY_HARNESS_SHA256);
  let encoded;
  try {
    encoded = await readFile(fixtureUrl, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    if (write) {
      console.log('info fixture missing; --write requires verified regeneration from the pinned object');
    } else {
      failures.push('fixture missing');
      console.log('FAIL fixture missing');
    }
  }
  if (encoded !== undefined) {
    check('fixture base64 hash', sha256(Buffer.from(encoded, 'utf8')), WEEKLY_ARCHIVE_B64_SHA256);
    const compressed = Buffer.from(encoded.trim(), 'base64');
    check('fixture compressed hash', sha256(compressed), WEEKLY_ARCHIVE_SHA256);
    const raw = gunzipSync(compressed);
    check('fixture uncompressed hash', sha256(raw), WEEKLY_ARCHIVE_UNCOMPRESSED_SHA256);
    console.log(`info fixture bytes base64=${encoded.length} compressed=${compressed.length} uncompressed=${raw.length}`);
  }
  const harnessBytes = await readFile(harnessUrl);
  check('harness hash', sha256(harnessBytes), REPLAY_HARNESS_SHA256);
  let hasObject = false;
  try {
    execFileSync('git', ['-C', root, 'cat-file', '-e', `${WEEKLY_IMPLEMENTATION_REVISION}^{commit}`], { stdio: 'ignore' });
    hasObject = true;
  } catch {
    console.log('info pinned git object absent; regeneration skipped, fixture check stands alone');
  }
  if (hasObject) {
    const tree = execFileSync('git', ['-C', root, 'rev-parse', `${WEEKLY_IMPLEMENTATION_REVISION}^{tree}`], { encoding: 'utf8' }).trim();
    check('git tree', tree, WEEKLY_IMPLEMENTATION_TREE);
    const raw = execFileSync('git', ['-C', root, 'archive', WEEKLY_IMPLEMENTATION_REVISION, 'src', 'package.json']);
    check('regenerated uncompressed hash', sha256(raw), WEEKLY_ARCHIVE_UNCOMPRESSED_SHA256);
    const compressed = execFileSync('gzip', ['-n'], { input: raw });
    check('regenerated compressed hash', sha256(compressed), WEEKLY_ARCHIVE_SHA256);
    const regenerated = execFileSync('base64', ['-w0'], { input: compressed, encoding: 'utf8' });
    check('regenerated base64 hash', sha256(Buffer.from(regenerated, 'utf8')), WEEKLY_ARCHIVE_B64_SHA256);
    if (write) {
      if (failures.length) {
        console.log('refusing to write while checks fail');
      } else {
        await writeFile(fixtureUrl, regenerated);
        console.log('wrote fixture from git regeneration (bytes identical to recorded hashes)');
      }
    }
  } else if (write) {
    failures.push('cannot write without pinned git object');
    console.log('FAIL cannot write without pinned git object');
  }
  if (failures.length) {
    console.error(`weekly reference check failed (${failures.length})`);
    for (const f of failures) console.error(`- ${f}`);
    process.exitCode = 1;
  } else {
    console.log('weekly reference check passed');
  }
}

await main();
